import Student from '../model/Student';



function Person({student}: {student: Student}) {
    return (
        <div className="student">
            <div className="avatar">
                <img src={student.photo} alt="" />
            </div>
            <h1>{student.name}</h1>
            <h2>{student.id}</h2>
            <p>性别：{student.sex} 年龄：{student.age}</p>
        </div>
    )
}

export default Person;
